(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20 + Math.cos(y*0.013-t*0.22)*14;
  const w1y = Math.cos(y*0.018-t*0.28)*20 + Math.sin(x*0.016+t*0.33)*14;
  const w2x = Math.sin((x+y)*0.008+t*0.15)*25 + Math.cos((x-y)*0.012-t*0.18)*18;
  const w2y = Math.cos((x-y)*0.009+t*0.2)*25 + Math.sin((x+y)*0.011+t*0.17)*18;
  const sx = x + w1x + w2x*0.5, sy = y + w1y + w2y*0.5;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 0.8],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.095, 1.7, 1.0],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 1.2],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 0.7],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 1.9, 0.9],
    [80+Math.sin(t*0.45+3)*70, 120+Math.cos(t*0.65+2)*55, 0.1, 2.1, 1.1],
    [400+Math.cos(t*0.38+6)*85, 180+Math.sin(t*0.48+4)*65, 0.07, 1.8, 0.75]
  ];
  let aS = 0, iS = 0, diff = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const a = Math.sin(d*f - t*sp);
    const b = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS += a * w; iS += b * w;
    diff += Math.sin(d*f*1.3 - t*sp*0.4 + a*0.5) * w * 0.3;
  }
  const tw = 8.4;
  const act = aS/tw, inh = iS/tw, dif = diff/tw;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*1.0))/2;
  const bg2 = Math.sin((sx+sy)*0.11+t*2.2)*0.25 + Math.sin((sx-sy)*0.09-t*1.8)*0.25;
  const bg3 = Math.sin(sx*0.06+sy*0.04-t*1.4)*Math.cos(sx*0.04-sy*0.07+t*0.9)*0.2;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.08-ang*2-t*2.5)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const voronoi = (px, py) => {
    let md = 99;
    for (let i = 0; i < 5; i++) {
      const vx = 120+Math.sin(t*0.3+i*1.3)*180, vy = 80+Math.cos(t*0.25+i*1.7)*70;
      md = Math.min(md, Math.sqrt((px-vx)**2+(py-vy)**2));
    }
    return md;
  };
  const vr = voronoi(sx, sy);
  const voro = Math.sin(vr*0.12-t*1.8)*0.25;
  const lap = (Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin(sx*0.15+1)*Math.sin(sy*0.15+2) + Math.sin(sx*0.15+2)*Math.sin(sy*0.15+1))/3;
  const cell = Math.tanh((lap + Math.sin((sx+sy)*0.08+t)*0.4)*1.5)*0.25;
  const cross = Math.sin(act*inh*3+t*0.5)*0.15;
  const raw = act - inh*0.65 + bg*0.25 + spiral + voro + cell + dif*0.4 + cross;
  const reaction = Math.tanh(raw*2.0);
  const blend = reaction*0.8 + cell*0.2;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,90],[12,78,108],[18,115,118],
    [45,148,120],[130,170,95],[195,175,65],[210,140,55],
    [195,90,50],[160,55,60],[110,30,55],[55,18,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.72?1.18:Math.abs(reaction)>0.5?1.06:1.0;
  const glow = Math.max(0, 1-Math.abs(reaction)*1.2)*0.08;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*80)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*120)|0)
  ];
}
